def num_subarray_bounded_max(nums, left, right):
    def count_at_most(bound):
        total = 0
        run_len = 0
        for num in nums:
            if num <= bound:
                run_len += 1
            else:
                run_len = 0
            total += run_len
        return total

    return count_at_most(right) - count_at_most(left - 1)

